CREATE OR REPLACE FUNCTION public.public_partner_stores() RETURNS TABLE(name text,logo_url text,description text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.name,p.logo_url,p.description FROM public.partner_stores p WHERE p.display_enabled = true $$;
REVOKE ALL ON FUNCTION public.public_partner_stores() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_partner_stores() TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.patch_store_display(_ids text[],_network text,_hidden boolean) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN UPDATE public.partner_catalog SET record=jsonb_set(record,'{site_hidden}',to_jsonb(_hidden),true) WHERE source=_network AND object_id=ANY(_ids); GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.patch_store_display(text[],text,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.patch_store_display(text[],text,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.set_partner_store_import(_id uuid,_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.partner_stores; BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO STRICT s FROM public.partner_stores WHERE id=_id FOR UPDATE; IF _enabled AND s.enrollment_status='not_enrolled' THEN RAISE EXCEPTION 'Anunciante não inscrito'; END IF; UPDATE public.partner_stores SET import_enabled=_enabled,updated_at=now() WHERE id=_id; IF s.network='awin' THEN IF _enabled THEN INSERT INTO public.awin_allowed_merchants(merchant_name) VALUES(s.merchant_name) ON CONFLICT DO NOTHING; ELSE DELETE FROM public.awin_allowed_merchants WHERE merchant_name=s.merchant_name; END IF; END IF; END $$;
REVOKE ALL ON FUNCTION public.set_partner_store_import(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_partner_store_import(uuid,boolean) TO authenticated,service_role;